CREATE OR ALTER PROCEDURE [dbo].[uspMenuChangeRequest_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @MenuId UNIQUEIDENTIFIER = NULL
	, @OriginalDishId UNIQUEIDENTIFIER = NULL
	, @RequestedDishId UNIQUEIDENTIFIER = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @RequestStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RequestNo]
			, t.[OrderId]
			, j1.[OrderNo] AS [OrderName]
			, t.[MenuId]
			, j2.[Name] AS [MenuName]
			, t.[OriginalDishId]
			, t.[RequestedDishId]
			, t.[MealDate]
			, t.[ShiftId]
			, j3.[Name] AS [ShiftName]
			, t.[Quantity]
			, t.[Reason]
			, t.[RequestedBy]
			, t.[RequestStatus]
			, t.[ApprovedBy]
			, t.[ApprovedAt]
			, t.[CreatedDate]
		FROM [dbo].[MenuChangeRequest] AS t
		LEFT JOIN [dbo].[Order] AS j1 ON j1.[Id] = t.[OrderId]
		LEFT JOIN [dbo].[Menu] AS j2 ON j2.[Id] = t.[MenuId]
		LEFT JOIN [dbo].[Shift] AS j3 ON j3.[Id] = t.[ShiftId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[RequestNo] LIKE CONCAT('%', @SearchText, '%'))
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (@MenuId IS NULL OR t.[MenuId] = @MenuId)
			AND (@OriginalDishId IS NULL OR t.[OriginalDishId] = @OriginalDishId)
			AND (@RequestedDishId IS NULL OR t.[RequestedDishId] = @RequestedDishId)
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (ISNULL(@RequestStatus, '') = '' OR t.[RequestStatus] = @RequestStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestNo' THEN r.[RequestNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestNo' THEN r.[RequestNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderName' THEN r.[OrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderName' THEN r.[OrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuId' THEN r.[MenuId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuId' THEN r.[MenuId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuName' THEN r.[MenuName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuName' THEN r.[MenuName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'originalDishId' THEN r.[OriginalDishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'originalDishId' THEN r.[OriginalDishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestedDishId' THEN r.[RequestedDishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestedDishId' THEN r.[RequestedDishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealDate' THEN r.[MealDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealDate' THEN r.[MealDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftName' THEN r.[ShiftName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftName' THEN r.[ShiftName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reason' THEN r.[Reason] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reason' THEN r.[Reason] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestedBy' THEN r.[RequestedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestedBy' THEN r.[RequestedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
